// ── CM360 CERTIFICATION (questões reais do Skillshop) ──
window.__quizData['cm360_cert'] = {
  id: 'cm360_cert',
  cert: 'Campaign Manager 360 Certification',
  icon: '📊',
  source: 'Google Skillshop',
  url: 'https://skillshop.exceedlms.com/student/path/8638-campaign-manager-certification-exam',
  questions: [
    { q: 'When is an impression counted in Reporting?', options: ['After the browser begins loading the webpage','After a user\'s device indicates that the creative download has begun','After the creative is served and viewed on the site','As soon as a creative is requested from the publisher'], correct: 1, explanation: 'CM360 counts an impression after the user\'s device signals that the creative download has begun — not when it\'s requested or fully viewed.', tags: ['CM360','impressão','reporting'] },
    { q: 'What attribution model uses Floodlight data from both attributed and non-attributed conversions?', options: ['Time Decay model','First Interaction model','Linear model','Data-driven model'], correct: 3, explanation: 'The Data-driven model uses Floodlight data from both attributed and non-attributed conversions to determine which touchpoints receive credit.', tags: ['CM360','atribuição','Floodlight','data-driven'] },
    { q: 'Which two methods count impressions on site-served creatives? (select two)', options: ['Mobile tracking ad','1×1 impression tracker','Tracking Ads','Click tracker ad'], correct: [1,2], explanation: '1×1 impression trackers and Tracking Ads are the two methods used to count impressions on site-served creatives in CM360.', tags: ['CM360','impressão','tracking'] },
    { q: 'What account structure should be used to share Floodlight tags and audience lists between multiple Advertisers?', options: ['Shared billing profiles','A single Floodlight activity','An account/advertiser relationship','A parent/child relationship'], correct: 3, explanation: 'A parent/child advertiser relationship in CM360 allows sharing Floodlight tags and audience lists between multiple advertisers.', tags: ['CM360','Floodlight','conta','hierarquia'] },
    { q: 'What HTML elements of a Floodlight tag\'s iFrame code identify the unique activity?', options: ['"src" and 1×1','"type" and "cat"','u1 and "fls"','1×1 and "ord"'], correct: 1, explanation: 'The "type" and "cat" parameters in the Floodlight iFrame tag identify the unique activity — "type" is the activity group tag and "cat" is the activity tag.', tags: ['CM360','Floodlight','HTML','tag'] },
    { q: 'What targeting rules display an ad to users who have viewed a product, but not purchased it?', options: ['Positively target all product viewers AND collect purchase IDs using u-variables','Negatively target all product purchasers AND collect purchase IDs using u-variables','Positively target all product purchasers AND negatively target all product viewers','Positively target all product viewers AND negatively target all product purchasers'], correct: 3, explanation: 'To show ads to cart abandoners: positively target viewers AND negatively target purchasers — this ensures you reach only those who showed interest but didn\'t convert.', tags: ['CM360','remarketing','targeting','audiência'] },
    { q: 'What data is provided in Video Verification?', options: ['Resolution and bit rate details','Information about ads that served on the same page','Asset and transcoding validation','Video player size and viewability'], correct: 3, explanation: 'Video Verification in CM360 provides data on video player size and viewability — measuring how visible and prominent the video ad was.', tags: ['CM360','video','viewability','verificação'] },
    { q: 'Where would purchased inventory for a campaign be entered in Campaign Manager?', options: ['Campaigns','Landing pages','Floodlight tags','Placements'], correct: 3, explanation: 'Placements in CM360 represent the purchased inventory — each placement corresponds to a specific ad unit on a publisher\'s site.', tags: ['CM360','placement','tráfego','inventário'] },
    { q: 'What feature can be used to combine log-level impression and click data for a custom reach analysis?', options: ['Line item filtering in Studio','GRP Insights','Attribution conversion segments','Data Transfer'], correct: 3, explanation: 'Data Transfer in CM360 provides log-level data (every impression and click) that can be exported to BigQuery or other tools for custom reach analysis.', tags: ['CM360','Data-Transfer','BigQuery','análise'] },
    { q: 'What report tracks Floodlight attribution in Reporting?', options: ['Floodlight impressions','Cookie Reach Overlap','Insights','Path to Conversion'], correct: 3, explanation: 'The Path to Conversion report shows all touchpoints (impressions and clicks) that led to a Floodlight conversion — the core attribution report in CM360.', tags: ['CM360','Path-to-Conversion','Floodlight','atribuição'] },
    { q: 'What timezone is used in Data Transfer (DT) timestamps for impression and click files?', options: ['The advertiser\'s timezone','Eastern Time (ET)','The user\'s timezone','Coordinated Universal Time (UTC)'], correct: 3, explanation: 'Data Transfer files use UTC (Coordinated Universal Time) for all timestamps — important when joining with data from other systems.', tags: ['CM360','Data-Transfer','UTC','timezone'] },
    { q: 'What Floodlight conversion counting method would report the first visit for each user within a given day?', options: ['Per session','Transactions','Standard','Unique'], correct: 3, explanation: '"Unique" counting in Floodlight records only the first conversion per user per day — ideal for measuring unique visitors to a confirmation page.', tags: ['CM360','Floodlight','conversão','unique'] },
    { q: 'What ad setting limits the number of times that ad can be shown to a particular user?', options: ['Impression ratio','Hard cut-off','Priority','Frequency cap'], correct: 3, explanation: 'Frequency cap in CM360 limits how many times a specific ad can be shown to the same user — set at the ad level within a placement.', tags: ['CM360','frequency-cap','frequência','ad'] },
    { q: 'When the primary HTML5 assets get delayed, what will serve in a user\'s browser as it\'s loading?', options: ['Backup image','.swf file','Default ad','Polite load image'], correct: 3, explanation: 'The polite load image serves as a placeholder while the primary HTML5 creative loads — it\'s a static image that displays until the main creative is ready.', tags: ['CM360','HTML5','creative','polite-load'] },
    { q: 'What cost model only calculates cost for impressions measured as viewable by Active View?', options: ['CPC','CPM','CPA','vCPM'], correct: 3, explanation: 'vCPM (viewable CPM) only charges for impressions that meet the Active View viewability standard — 50% of pixels visible for at least 1 second for display.', tags: ['CM360','vCPM','Active-View','viewability'] },
    { q: 'When would a VPAID asset be used?', options: ['When VAST is not supported','For videos served on mobile devices','As a backup for a VAST asset','When a video ad contains interactive features'], correct: 3, explanation: 'VPAID (Video Player Ad-Serving Interface Definition) enables interactive video ads — clickable overlays, mini-games, interactive elements within the video player.', tags: ['CM360','VPAID','VAST','video','interativo'] },
    { q: 'What happens when a user meets the frequency cap for an ad?', options: ['The placement stops serving to that user','Ads serve at a lower CPM','Ads stop serving to that user','Another ad or a default ad is served'], correct: 3, explanation: 'When a user meets the frequency cap for an ad, CM360 serves another eligible ad or the placement\'s default ad — the user continues to see ads, just not that specific one.', tags: ['CM360','frequency-cap','default-ad'] },
    { q: 'What counting method tracks the number of sales made or items purchased?', options: ['Counter activities','Custom Floodlight variables','Standard counting','Sales activities'], correct: 3, explanation: 'Sales activities in Floodlight track quantity and revenue — capturing the number of items sold and total transaction value via the "qty" and "cost" parameters.', tags: ['CM360','Floodlight','Sales','e-commerce'] },
    { q: 'To set ad status to "active," which two objects must be assigned to an ad?', options: ['A frequency cap','A priority','A placement','An active creative'], correct: [2,3], explanation: 'An ad in CM360 requires both a placement (where to serve) and an active creative (what to serve) before it can be set to active status.', tags: ['CM360','ad','placement','creative','status'] },
    { q: 'What must a Floodlight tag include to capture product data alongside a conversion?', options: ['Dynamic pixels','An ord value','1×1 tracking pixel','Custom Floodlight variable'], correct: 3, explanation: 'Custom Floodlight variables (u1=, u2=, etc.) capture additional data alongside conversions — product IDs, SKUs, categories, or any custom dimension.', tags: ['CM360','Floodlight','custom-variable','produto'] },
    { q: 'Where are Campaign Manager and Display & Video 360 linked?', options: ['Admin subaccounts','Advertiser properties','Campaign properties','Floodlight configuration'], correct: 3, explanation: 'CM360 and DV360 are linked in the Floodlight configuration — the DV360 partner ID is added as an association in the CM360 advertiser\'s Floodlight settings.', tags: ['CM360','DV360','Floodlight','integração'] },
    { q: 'Audience lists created in Campaign Manager can be automatically shared with which linked applications? (select three)', options: ['Studio','Display & Video 360','Search Ads 360','Google Ads'], correct: [1,2,3], explanation: 'CM360 audience lists automatically sync with DV360, SA360, and Google Ads when they are linked — enabling cross-platform remarketing from a single Floodlight source.', tags: ['CM360','audience','remarketing','DV360','SA360','Google-Ads'] },
    { q: 'What report in Report Builder shows the number of unique users who have interacted with ads?', options: ['Standard','Path to Conversion','GRP','Cookie Reach Overlap'], correct: 3, explanation: 'Cookie Reach Overlap report in CM360 shows unique user reach — how many unduplicated users were exposed to ads across placements, sites, or campaigns.', tags: ['CM360','Cookie-Reach','relatório','único'] },
    { q: 'Which two tabs in Reporting provide access to viewability data? (select two)', options: ['Attribution','Summary','Report Builder','Verification'], correct: [2,3], explanation: 'Both Report Builder (where you can add Active View metrics to standard reports) and Verification (dedicated viewability analysis) provide viewability data in CM360.', tags: ['CM360','viewability','Report-Builder','Verification'] },
    { q: 'What ad setting ensures a qualified user will always be served a city-targeted ad first over a country-targeted ad?', options: ['Frequency cap','Keyword targeting','Dynamic targeting keys','Priority'], correct: 3, explanation: 'Priority in CM360 determines which ad serves when multiple ads are eligible — a higher priority city-targeted ad will always win over a lower priority country-targeted ad.', tags: ['CM360','priority','targeting','ad'] },
    { q: 'If a publisher serves a placement tag after the campaign end date, what ad will serve?', options: ['A random ad','Nothing will serve','The backup image','The default ad'], correct: 3, explanation: 'After the campaign end date, CM360 serves the default ad (a simple static backup) — ensuring the publisher\'s placement always has something to display.', tags: ['CM360','default-ad','campanha','end-date'] },
  ]
};

// ── DV360 CERTIFICATION (questões reais do Skillshop) ──
window.__quizData['dv360_cert'] = {
  id: 'dv360_cert',
  cert: 'Display & Video 360 Certification',
  icon: '🎯',
  source: 'Google Skillshop',
  url: 'https://skillshop.exceedlms.com/student/path/8636-display-video-360-certification-exam',
  questions: [
    { q: 'To activate the creative approvals process for a new creative, what step must be taken?', options: ['Set the creative to active','Upload the creative to Display & Video 360','Resubmit the creative for approval','Assign the creative to an active line item'], correct: 3, explanation: 'Creative audit in DV360 is triggered by assigning the creative to an active line item — the platform then submits it to the exchange for review.', tags: ['DV360','creative','aprovação','audit'] },
    { q: 'What inventory sources allow for exclusive publisher partnerships?', options: ['Automatic Deals and preferred deals','Exchanges and preferred deals','Automatic Deals and private auctions','Preferred deals and private auctions'], correct: 3, explanation: 'Preferred deals (fixed price, non-guaranteed) and private auctions (PMP) both allow exclusive publisher partnerships — unlike open exchange which is available to all buyers.', tags: ['DV360','Deal','PMP','publisher','inventário'] },
    { q: 'What is the correct Display & Video 360 account hierarchy?', options: ['Partner > Campaign > Advertiser > Insertion order > Line item > Creative','Insertion order > Partner > Line > Advertiser','Account > Line item > Advertiser > Insertion order > Partner','Partner > Advertiser > Campaign > Insertion order > Line item > Creative'], correct: 3, explanation: 'DV360 hierarchy: Partner (agency/holding company) > Advertiser > Campaign > Insertion Order (IO) > Line Item > Creative. Understanding this is essential for structuring campaigns.', tags: ['DV360','hierarquia','estrutura','conta'] },
    { q: 'What insertion order settings must be set before a campaign can go live?', options: ['Auto-budget allocation and targeting','Bids and creatives','Bid multipliers and goals','Budgets and flight dates'], correct: 3, explanation: 'Budget and flight dates are the two required settings for an Insertion Order before a DV360 campaign can go live — without them the IO cannot become active.', tags: ['DV360','IO','budget','flight-dates','go-live'] },
    { q: 'What feature allows users to adjust fixed bids for different geographies or device types?', options: ['Partner revenue model','Viewability targeting','Recency targeting','Bid multipliers'], correct: 3, explanation: 'Bid multipliers in DV360 let you increase or decrease fixed bids by percentage for specific targeting dimensions — e.g., +20% for mobile, +15% for São Paulo geo.', tags: ['DV360','bid-multiplier','lance','geo','device'] },
    { q: 'When is a "view" counted for TrueView campaigns?', options: ['Each time Active View recognizes TrueView','Each time the user watches at least two seconds of the video','Each time a video\'s screen is 50% viewable on the page','Each time the user clicks or watches 30 seconds or the entire video'], correct: 3, explanation: 'TrueView view is counted when: (1) user watches 30 seconds of the video (or complete if shorter), OR (2) user clicks on the ad. This is why CPV (cost per view) is the metric.', tags: ['DV360','TrueView','YouTube','view','CPV'] },
    { q: 'What format cannot share a frequency cap with other media formats?', options: ['Native','Video','Display','TrueView'], correct: 3, explanation: 'TrueView (YouTube) cannot share frequency caps with other media formats in DV360 — it uses a separate frequency management system within YouTube\'s infrastructure.', tags: ['DV360','TrueView','frequency-cap','formato'] },
    { q: 'At what levels can pacing be set?', options: ['Line item and ad group','Campaign and insertion order','Campaign and line item','Insertion order and line item'], correct: 3, explanation: 'Pacing in DV360 can be set at both the Insertion Order and Line Item levels — IO pacing controls overall flight spend, LI pacing controls individual tactic delivery.', tags: ['DV360','pacing','IO','Line-Item'] },
    { q: 'How are line items affected when a user edits the default targeting for insertion orders?', options: ['Existing and new line items apply the original default targeting','New line items inherit the new default targeting and existing line items inherit edits to default geotargeting','New and existing line items inherit the new insertion order targeting','Existing line items are unaffected and new line items inherit the new default targeting'], correct: 3, explanation: 'IO default targeting only applies to NEW line items created after the change — existing line items retain their own targeting settings and are not retroactively updated.', tags: ['DV360','targeting','IO','Line-Item','default'] },
    { q: 'What is one benefit of applying "auto budget allocation" to an insertion order\'s budget settings?', options: ['The system will apply new budgets based on the insertion order\'s goal','Budget segments will automatically actualize and allocate to future segments','The system automatically provides budget suggestions to the Quality metrics','The system automatically moves budget to higher performing line items'], correct: 3, explanation: 'Auto budget allocation in DV360 dynamically shifts budget between line items within an IO based on performance — line items that are spending efficiently get more budget automatically.', tags: ['DV360','auto-budget','otimização','IO'] },
    { q: 'What is a benefit of linking a YouTube channel to the advertiser in Display & Video 360?', options: ['Access to YouTube masthead inventory','Access to Floodlight tag tracking without using dynamic pixels','Availability to frequency caps on all media buys across YouTube and other exchanges','Access to earned metrics, like shares, and channel subscribers'], correct: 3, explanation: 'Linking a YouTube channel to a DV360 advertiser unlocks earned metrics — shares, likes, channel subscribers, views — providing a fuller picture of TrueView campaign impact.', tags: ['DV360','YouTube','earned-metrics','TrueView'] },
    { q: 'What should be used to investigate why a line item isn\'t winning the majority of qualifying open auction impressions?', options: ['A General or Standard report grouped by channel','The "Line Item Settings" CSV','The Inventory Marketplace forecast','The line item\'s impressions lost chart'], correct: 3, explanation: 'The Impressions Lost chart in DV360 breaks down why a line item is not winning auctions — low bid, budget exhausted, brand safety exclusions, targeting too narrow, creative rejected.', tags: ['DV360','Line-Item','troubleshoot','impressions-lost'] },
    { q: 'To optimize the campaign towards viewability, which two approaches can an advertiser take? (select two)', options: ['Only target inventory displayed on mobile apps','Add a pixel to the Default tag in Campaign Manager','Set the bid strategy to viewable CPM (vCPM)','Assign viewability targeting'], correct: [2,3], explanation: 'vCPM bid strategy (only pay for viewable impressions) + viewability targeting (filter inventory by predicted viewability %) are the two native DV360 approaches to optimize for viewability.', tags: ['DV360','viewability','vCPM','otimização'] },
    { q: 'How can a site be blacklisted from an advertiser\'s media buys?', options: ['Add the URL to the advertiser\'s URL field','Identify the website\'s key phrases and use them in keyword exclusion targeting','Use the audience composition report and exclude audiences that visit that site','Add the URL to a channel that is assigned to the advertiser\'s exclusionary channel targeting'], correct: 3, explanation: 'To block a site in DV360: create a Channel containing the domain > assign that channel as Exclusionary targeting at the advertiser or line item level.', tags: ['DV360','blocklist','channel','brand-safety','exclusão'] },
    { q: 'What does an audit status of "Pending, servable" mean?', options: ['The creative will serve but is prohibited due to unsuitable content','The creative will not serve for 24 hours','The creative will not serve until resubmitted for approval','The creative will serve but may be rejected after policy review'], correct: 3, explanation: '"Pending, servable" means the creative is live and delivering, but is still under policy review — it may be rejected retroactively if found to violate policies.', tags: ['DV360','creative','audit','status','pending'] },
    { q: 'How is the daily budget calculated for an insertion order with Flight Even pacing?', options: ['The flight budget divided by the number of remaining days and multiplied by 1.5','The remaining flight budget multiplied by the number of days remaining','The campaign\'s budget, minus the flight budget spent, divided by the number of days remaining','The remaining flight budget divided by the number of days remaining'], correct: 3, explanation: 'Flight Even pacing calculates daily budget as: Remaining flight budget ÷ Number of days remaining in the flight. This recalculates daily to catch up or slow down as needed.', tags: ['DV360','pacing','Even','budget','flight'] },
    { q: 'What percentage of the daily budget is applied when using "Ahead" pacing?', options: ['150% of the budget, based on budget segments and KPIs','200% of the daily budget, based on inventory','It\'s not a specific percentage, it\'s solely based on performance','120% of the daily budget, based on the flight dates'], correct: 3, explanation: '"Ahead" pacing in DV360 spends up to 120% of the calculated daily budget when inventory is available — designed to ensure budget is spent by the end of the flight.', tags: ['DV360','pacing','Ahead','budget','120%'] },
    { q: 'How does the setup for a Programmatic Guaranteed deal differ from a preferred deal?', options: ['Programmatic Guaranteed deals are available in the insertion order\'s Inventory source targeting','The publisher sets up line items in Display & Video 360 for any Programmatic Guaranteed deals','The publisher needs to agree on the targeting and categories for an open auction deal','The publisher needs to agree on number of impressions and fixed price for a Programmatic Guaranteed deal'], correct: 3, explanation: 'Programmatic Guaranteed (PG) requires negotiating a guaranteed number of impressions at a fixed CPM — the publisher commits to delivering that volume. Preferred deals have no impression guarantee.', tags: ['DV360','Programmatic-Guaranteed','PG','Deal','publisher'] },
    { q: 'What is the difference between Programmatic Guaranteed deals and preferred deals?', options: ['Preferred deals do not allow targeting edits in Display & Video 360','Programmatic Guaranteed deals are incompatible with conversion pixels','Preferred deals have required minimum spend','Programmatic Guaranteed deals have required minimum spend'], correct: 3, explanation: 'PG deals have a required minimum spend (committed impressions × fixed CPM). Preferred deals are non-guaranteed — the buyer can choose whether to bid on each available impression.', tags: ['DV360','PG','Preferred-Deal','garantia','spend'] },
    { q: 'What are two Google Audiences? (select two)', options: ['First-party','Third-party','In Market','Affinity'], correct: [2,3], explanation: 'In-Market (users actively researching a purchase) and Affinity (users with demonstrated long-term interests) are Google\'s proprietary audience types available in DV360 and Google Ads.', tags: ['DV360','Google-Audiences','In-Market','Affinity','targeting'] },
    { q: 'What is the result of using a VPAID tag instead of a VAST tag when running video ads?', options: ['The ability to run on TrueView inventory','More available inventory across all devices','Less functionality for engagement and interaction with ad','Less available inventory across all devices'], correct: 3, explanation: 'VPAID tags limit inventory — many publishers and apps only accept VAST. VPAID also doesn\'t work on mobile apps or CTV. Use VAST for maximum reach, VPAID only when interactivity is required.', tags: ['DV360','VPAID','VAST','video','inventário'] },
    { q: 'How would you add third-party verification to a creative when Campaign Manager is your ad server?', options: ['Download the Campaign Manager tag, append to the Display & Video 360 tag, and perform a SDF bulk upload','Add the Display & Video 360 tags to Campaign Manager with the third party verification\'s tracking link','Add the integration code to the advertiser\'s Basic Details and upload the tags to Display & Video 360','In Display & Video 360, use the custom tag wrapper feature'], correct: 3, explanation: 'When CM360 is the ad server, add 3rd party verification (DoubleVerify, IAS) in DV360 using the custom tag wrapper — it wraps around the CM360 tag to apply verification without modifying the original tag.', tags: ['DV360','DoubleVerify','IAS','verificação','tag-wrapper'] },
    { q: 'What environment supports proximity targeting?', options: ['Mobile Web','Desktop Web on Mobile','TrueView','Mobile App'], correct: 3, explanation: 'Proximity targeting (geo-fencing by specific location radius) in DV360 is only supported in the Mobile App environment — it relies on GPS data from apps, unavailable on mobile web.', tags: ['DV360','proximity-targeting','Mobile-App','geo'] },
    { q: 'Which ad format supports pre-bid verification with Integral Ad Science?', options: ['Bumpers','Mobile app','TrueView','Display'], correct: 3, explanation: 'IAS pre-bid verification in DV360 is supported for Display (standard banners) — it filters impressions before bidding based on IAS\'s predicted brand safety and viewability scores.', tags: ['DV360','IAS','pre-bid','Display','brand-safety'] },
    { q: 'What line items are impacted by insertion order default targeting?', options: ['All current line items','TrueView line items','Only video line items','New line items only, not current line items'], correct: 3, explanation: 'IO default targeting only propagates to NEW line items created after the targeting is set. Existing line items maintain their own targeting settings independently.', tags: ['DV360','IO','Line-Item','default-targeting'] },
  ]
};

// ── AMAZON ADVERTISING FOUNDATIONS (estilo das questões reais) ──
window.__quizData['amazon_cert'] = {
  id: 'amazon_cert',
  cert: 'Amazon Advertising Foundations Certification',
  icon: '📦',
  source: 'Amazon Ads Learning Console',
  url: 'https://learningconsole.amazonadvertising.com/student/path/1540',
  questions: [
    { q: 'An advertiser wants to reach customers who have recently viewed products similar to theirs but haven\'t purchased. Which Amazon audience should they use?', options: ['Lifestyle audiences','In-market audiences','Advertiser audiences (remarketing)','Contextual targeting'], correct: 1, explanation: 'In-market audiences on Amazon contain shoppers who have recently researched and purchased products in a category — they\'re actively considering a purchase, making them high-intent targets.', tags: ['Amazon','In-Market','audiência','targeting'] },
    { q: 'Which metric measures the percentage of total attributed sales that came from advertising spend?', options: ['ROAS','NTB Rate','ACOS','Click-through rate'], correct: 2, explanation: 'ACoS (Advertising Cost of Sales) = Ad spend ÷ Attributed sales × 100. It\'s the primary efficiency metric for Amazon Sponsored ads — lower ACoS means more efficient advertising.', tags: ['Amazon','ACoS','métricas','eficiência'] },
    { q: 'If Kitchen Smart wants to create a Sponsored Products campaign for their toasters by targeting similar ASINs from other brands, which targeting method should they use?', options: ['Keyword targeting — broad match','Automatic targeting — loose match','Keyword targeting — exact match','Product targeting — product (ASIN) targeting'], correct: 3, explanation: 'Product targeting by ASIN allows advertisers to show ads specifically on the detail pages of competitor or complementary products — ideal for conquest campaigns.', tags: ['Amazon','ASIN','Product-targeting','Sponsored-Products'] },
    { q: 'True or false: If an advertiser\'s goal is sales efficiency, they should decrease bids on keywords with high ACoS.', options: ['True','False'], correct: 0, explanation: 'True — high ACoS means the keyword costs more in ads than it generates in attributed sales. Decreasing bids on inefficient keywords reduces wasted spend and improves overall campaign ACoS.', tags: ['Amazon','ACoS','eficiência','lance'] },
    { q: 'Where will a customer be directed after clicking on a product featured in a Sponsored Brands ad?', options: ['The advertiser\'s Amazon Store or a custom landing page','The advertiser\'s website','The Amazon search results page for the brand','A brand-curated video on Amazon\'s homepage'], correct: 0, explanation: 'Sponsored Brands ads can direct customers to either the brand\'s Amazon Store or a custom landing page showcasing multiple products — this is a key differentiator from Sponsored Products.', tags: ['Amazon','Sponsored-Brands','Store','landing-page'] },
    { q: 'Amazon may adjust a bid in real time up to 100% when an ad may be more likely to convert to a sale. What is this describing?', options: ['Manual bidding','Fixed bidding','ROAS target bidding','Dynamic bids — up and down'], correct: 3, explanation: 'Dynamic bids (up and down) allow Amazon to increase bids by up to 100% when a conversion is likely and decrease by up to 100% when it\'s unlikely — Amazon\'s Smart Bidding equivalent.', tags: ['Amazon','Dynamic-bids','lance','automático'] },
    { q: 'Which of the following automatic targeting options would show your ad to shoppers who view the detail pages of products similar to yours?', options: ['Close match','Loose match','Complements','Substitutes'], correct: 3, explanation: 'Substitutes automatic targeting shows ads to shoppers viewing product detail pages of products similar to yours — competitor products. Close/Loose match are keyword-based; Complements targets accessory products.', tags: ['Amazon','Substitutes','targeting','automático'] },
    { q: 'After you create a Sponsored Brands campaign with a lifetime budget, you can increase the budget but you can\'t decrease it.', options: ['True','False'], correct: 0, explanation: 'True — Sponsored Brands campaigns with lifetime budgets allow budget increases but not decreases after launch. This protects publisher revenue and ensures campaign continuity.', tags: ['Amazon','Sponsored-Brands','budget','lifetime'] },
    { q: 'True or false? Cancelled orders are not included in sales attribution metrics.', options: ['True','False'], correct: 0, explanation: 'True — Amazon excludes cancelled and returned orders from sales attribution. Attributed sales reflect only completed purchases within the attribution window.', tags: ['Amazon','atribuição','cancelled-orders','métricas'] },
    { q: 'Which Amazon DSP audience type is made up of Amazon\'s own first-party shopping and viewing data?', options: ['Third-party audiences','Contextual segments','Advertiser audiences','Amazon audiences'], correct: 3, explanation: 'Amazon Audiences are built from Amazon\'s proprietary first-party data — purchase history, search behavior, product views, Prime Video watching — available exclusively through Amazon DSP.', tags: ['Amazon','DSP','first-party','Amazon-Audiences'] },
  ]
};

// ── META BLUEPRINT (estilo das questões reais) ──
window.__quizData['meta_blueprint'] = {
  id: 'meta_blueprint',
  cert: 'Meta Blueprint Certification (100-101)',
  icon: '📘',
  source: 'Meta Blueprint',
  url: 'https://www.facebook.com/business/learn/certification',
  questions: [
    { q: 'What does the Meta Pixel allow advertisers to do?', options: ['Purchase ads directly from the Facebook feed','Automatically create a product catalog from the website','Manage organic posts on a Facebook Page','Track actions taken on their website and create audiences based on those actions'], correct: 3, explanation: 'The Meta Pixel is a JavaScript snippet that tracks website visitor behavior — page views, purchases, add-to-carts — enabling conversion measurement, optimization, and remarketing audience creation.', tags: ['Meta','Pixel','tracking','conversão'] },
    { q: 'An advertiser wants to reach people who are similar to their existing customers. Which targeting option should they use?', options: ['Detailed Targeting (Interests)','Location Targeting','Custom Audience — Website Visitors','Lookalike Audience'], correct: 3, explanation: 'Lookalike Audiences find people who share characteristics with a source audience (customers, pixel visitors, engagers) — Meta\'s algorithm identifies patterns and finds similar users.', tags: ['Meta','Lookalike','audiência','targeting'] },
    { q: 'Which campaign objective should be selected when the goal is to drive purchases on a website?', options: ['Awareness','Traffic','Engagement','Sales'], correct: 3, explanation: 'The Sales objective (formerly "Conversions") optimizes ad delivery for purchase events — Meta shows ads to people most likely to complete a purchase based on their behavioral signals.', tags: ['Meta','objetivo','Sales','conversão'] },
    { q: 'What is the recommended minimum audience size for a Lookalike Audience source?', options: ['At least 100 people in the source country','At least 500 people in the source country','At least 1,000 people in the source country','At least 1,500 people in the source country'], correct: 2, explanation: 'Meta recommends at least 1,000 people in the source audience for a Lookalike to ensure sufficient signal. Smaller sources can reduce quality of the lookalike model.', tags: ['Meta','Lookalike','tamanho','audiência'] },
    { q: 'What is Advantage+ Audience?', options: ['A manually configured audience with detailed interest targeting','Meta\'s AI-powered audience automation that finds the best audience for your ads','An audience made from first-party email lists','A lookalike audience based on pixel data'], correct: 1, explanation: 'Advantage+ Audience is Meta\'s fully automated audience targeting — advertisers provide optional audience hints, but Meta\'s AI decides who to show ads to for optimal performance.', tags: ['Meta','Advantage+','automação','AI','audiência'] },
    { q: 'What does "Frequency" measure in Meta Ads reporting?', options: ['The number of unique people who saw the ad','The total number of times the ad was displayed','The average number of times each person saw the ad','The percentage of the target audience reached'], correct: 2, explanation: 'Frequency = Total Impressions ÷ Total Reach. It measures the average number of times each unique person saw your ad. High frequency (>3-4) can indicate ad fatigue.', tags: ['Meta','frequência','impressões','alcance','métricas'] },
    { q: 'What is the benefit of using Advantage+ Placements?', options: ['It allows choosing specific placements manually for maximum control','It reduces CPM by restricting delivery to Facebook Feed only','It limits delivery to Instagram only for younger demographics','It optimizes delivery across all Meta placements to find where performance is best'], correct: 3, explanation: 'Advantage+ Placements (formerly Automatic Placements) lets Meta\'s algorithm find the most cost-effective placement mix — often outperforming manual placement selection.', tags: ['Meta','Advantage+','placements','Feed','Instagram'] },
    { q: 'What is the Facebook Business Manager used for?', options: ['Creating organic posts on Facebook Pages','Accessing Facebook\'s marketplace for buying products','Measuring SEO performance of business websites','Managing multiple ad accounts, Pages, and teams in one centralized location'], correct: 3, explanation: 'Business Manager (now Meta Business Suite) is the central hub for managing multiple ad accounts, Pages, team permissions, billing, and assets — essential for agencies and multi-brand advertisers.', tags: ['Meta','Business-Manager','conta','gestão'] },
    { q: 'Which of the following is a valid use of a Custom Audience in Meta Ads?', options: ['Targeting users based on their age and location only','Reaching people who have interacted with your Instagram profile','Showing ads to all users in a specific country','Targeting users based on their income level'], correct: 1, explanation: 'A Custom Audience can be created from Instagram profile interactions — people who visited your profile, liked a post, sent a DM, or saved a post — enabling warm audience remarketing.', tags: ['Meta','Custom-Audience','Instagram','remarketing'] },
    { q: 'What is a Conversion API (CAPI) and why was it introduced?', options: ['A tool for creating automated posts on Facebook','An API that allows organic reach optimization','A Meta tool for managing influencer partnerships','A server-side integration that sends conversion data directly to Meta, improving tracking accuracy post-iOS14'], correct: 3, explanation: 'CAPI (Conversions API) bypasses browser limitations caused by iOS14 App Tracking Transparency and ad blockers by sending events server-to-server — improving signal quality and attribution accuracy.', tags: ['Meta','CAPI','iOS14','server-side','privacidade'] },
  ]
};

