window.__quizData['google_video'] = {
  id: 'google_video',
  cert: 'Google Ads Video Certification',
  icon: '▶️',
  source: 'Google Skillshop',
  url: 'https://skillshop.docebosaas.com/learn/courses/7633/google-ads-video-certification',
  questions: [
    { q: 'You\'re running a Google video campaign with an awareness goal and want to understand if it shifts user perception or behaviour. Which measurement solution should you use?', options: ['Unique reach report','Video played to report','Brand Lift','Conversion tracking'], correct: 2, explanation: 'Brand Lift measures the impact of video campaigns on upper-funnel metrics like ad recall, brand awareness, and purchase intent — exactly what you need to measure perception/behaviour shifts from an awareness campaign.', tags: ['Video','Brand-Lift','awareness','measurement'] },
    { q: 'You\'re planning to run a video campaign with an awareness goal and want to measure how many people were served your ads and how many times across devices. What measurement solution should you use?', options: ['Brand Lift','Conversion tracking','Unique reach','View rate report'], correct: 2, explanation: 'Unique Reach measures the number of unique users reached and the average frequency with which they were served your ads — the key cross-device reach and frequency metric for awareness campaigns.', tags: ['Video','Unique-Reach','awareness','frequency','cross-device'] },
    { q: 'You\'re running a video campaign with a consideration goal and want to measure how many people watched your video. Which measurement solution should you use?', options: ['Brand Lift','Unique reach','Conversion tracking','View rate / Quartile reporting'], correct: 3, explanation: 'For consideration, use View Rate and Quartile reporting (Video played to 25%/50%/75%/100%) — these show how many people engaged with your video content and how deeply they watched.', tags: ['Video','consideration','view-rate','quartile','measurement'] },
    { q: 'You\'re running a consideration campaign and want to measure if it influences viewer perception or purchase intent. Which measurement solution should you use?', options: ['Unique reach','Conversion tracking','View rate report','Brand Lift'], correct: 3, explanation: 'Brand Lift measures shifts in consideration metrics like purchase intent, brand interest, and favourability — perfect for measuring whether a consideration campaign is actually changing how viewers think about your brand.', tags: ['Video','Brand-Lift','consideration','purchase-intent'] },
    { q: 'Your goal is to increase retention and loyalty for your brand. What type of Google video campaign should you use?', options: ['Video action campaign','Bumper ads campaign','Video reach campaign','Video for brand consideration'], correct: 3, explanation: 'Brand consideration campaigns (using skippable in-stream and in-feed video ads) build deeper engagement and loyalty — encouraging viewers to actively seek out more content or visit your site, fostering retention.', tags: ['Video','consideration','loyalty','retention'] },
    { q: 'Your goal is to increase purchase intent for your products. What type of Google video campaign should you use?', options: ['Video reach campaign','Video action campaign','Bumper ads campaign','Video for brand consideration'], correct: 3, explanation: 'Video for brand consideration (using skippable in-stream and in-feed/discovery ads with CPV bidding) is designed specifically to drive consideration and purchase intent — getting viewers to explore your products.', tags: ['Video','consideration','purchase-intent','CPV'] },
    { q: 'You have a goal to increase scale and improve CPA performance. Which marketing objective aligns to this goal?', options: ['Brand awareness and reach','Brand consideration','Drive conversions','Influencer marketing'], correct: 2, explanation: 'Drive conversions (action objective) using Video Action Campaigns with Smart Bidding (tCPA, tROAS, Maximize conversions) is designed to scale while improving CPA efficiency — exactly this goal.', tags: ['Video','action','conversions','CPA','Smart-Bidding'] },
    { q: 'A business wants their video campaign to make people think of their brand in decision-making moments. What marketing objective connects to this goal?', options: ['Brand awareness and reach','Drive conversions','Brand consideration','Product and brand consideration'], correct: 3, explanation: 'Product and brand consideration (brand consideration objective) is specifically about influencing viewers during high-intent moments — making your brand top of mind when they\'re ready to decide.', tags: ['Video','consideration','decision-making','brand'] },
    { q: 'What video ad formats are optimised to drive action among potential customers in decision-making moments?', options: ['Bumper ads and Non-skippable in-stream','Masthead and Bumper ads','Skippable in-stream and in-feed video ads','Video action campaigns and responsive video ads'], correct: 3, explanation: 'Video action campaigns use skippable in-stream and in-feed/YouTube Shorts ads with CTA overlays and sitelinks — specifically designed to drive measurable actions at decision-making moments.', tags: ['Video','action','VAC','responsive-video','CTA'] },
    { q: 'What two video ad formats are optimised for engagement and designed to help customers think of you first when they\'re looking to buy?', options: ['Bumper ads and Masthead','Non-skippable in-stream and Bumper','Skippable in-stream and Masthead','Skippable in-stream and in-feed video ads'], correct: 3, explanation: 'For consideration, skippable in-stream ads (viewers choose to watch) and in-feed/discovery ads (viewers actively find your content) signal genuine interest and drive consideration more effectively than forced-view formats.', tags: ['Video','consideration','skippable','in-feed'] },
    { q: 'You know mixing video ad formats is a good idea. For maximum reach on a minimum budget, what mix of awareness formats should you use?', options: ['Skippable in-stream only','Non-skippable in-stream and skippable in-stream','Bumper ads only','Bumper ads and skippable in-stream ads'], correct: 3, explanation: 'Bumper ads (6-second, non-skippable, CPM) + skippable in-stream = maximum budget efficiency for reach. Bumpers are the cheapest awareness format; adding skippables extends reach to audiences who engage more.', tags: ['Video','awareness','bumper','skippable','reach','budget'] },
    { q: 'For maximum reach and video completions, what mix of awareness ad formats should you use?', options: ['Bumper ads only','Skippable in-stream only','Non-skippable in-stream only','Non-skippable in-stream and bumper ads'], correct: 3, explanation: 'Non-skippable in-stream (15-second, guaranteed full view) + bumper ads (6-second, guaranteed view) = maximum completions. Both formats ensure 100% of served impressions result in complete ad views.', tags: ['Video','awareness','non-skippable','bumper','completions'] },
    { q: 'You ran a successful 30-second awareness campaign and want to remarket to audiences who saw it with shorter, memorable ads. What video ad format should you use?', options: ['In-feed video ads','Skippable in-stream ads','Non-skippable in-stream ads','Bumper ads'], correct: 3, explanation: 'Bumper ads (6 seconds) are ideal for remarketing to awareness audiences — they reinforce the longer ad\'s message with a quick, memorable reminder. They\'re designed as a "last impression" before purchase.', tags: ['Video','bumper','remarketing','6-second'] },
    { q: 'What\'s the benefit of using video ad sequencing for a consideration campaign?', options: ['It guarantees 100% view rates','It reduces CPM costs','It automatically generates video creative','It tells a brand story in chapters across multiple ads to guide viewers along the consideration journey'], correct: 3, explanation: 'Video ad sequencing serves multiple ads in a defined order to the same user — telling a story in chapters. This guided narrative approach is more effective for driving consideration than isolated single ads.', tags: ['Video','sequencing','consideration','narrative','story'] },
    { q: 'You want to reach cooking enthusiasts with your video campaign. What audience solution should you use?', options: ['Demographic targeting','Customer Match','In-market audiences','Affinity audiences'], correct: 3, explanation: 'Affinity audiences (like "Cooking Enthusiasts") target people based on their long-term interests and passions — ideal for awareness and consideration when you want to reach people who genuinely love a topic.', tags: ['Video','affinity','audiences','targeting','interests'] },
    { q: 'You want to reach people actively looking to buy certain products in the near future to grow consideration. What audience solution should you use?', options: ['Affinity audiences','Customer Match','Life events','In-market audiences'], correct: 3, explanation: 'In-market audiences target people actively researching and comparing products/services in a specific category — they\'re in the decision phase, making them ideal for consideration and action campaigns.', tags: ['Video','in-market','consideration','purchase-intent','audiences'] },
    { q: 'You want to reach male users aged 35-44 with your video campaign. What audience solution should you use?', options: ['Affinity audiences','In-market audiences','Customer Match','Demographic targeting'], correct: 3, explanation: 'Demographic targeting (age, gender, parental status, household income) lets you directly specify who sees your ads based on demographic attributes — the straightforward solution for demographic-specific targeting.', tags: ['Video','demographics','targeting','age','gender'] },
    { q: 'You want to reach people based on their interests without building audiences manually. What audience solution should you use?', options: ['Customer Match','Demographic targeting','In-market audiences','Optimised targeting'], correct: 3, explanation: 'Optimised targeting uses Google\'s AI to automatically find audiences likely to convert, going beyond manually-defined segments — no manual audience building required while still reaching interest-based users.', tags: ['Video','optimised-targeting','AI','automação'] },
    { q: 'You want to reach people who browsed similar websites to yours with your video campaign. What audience solution should you use?', options: ['Affinity audiences','In-market audiences','Demographic targeting','Similar segments / Similar audiences'], correct: 3, explanation: 'Similar segments (similar audiences) find new users who share traits with your existing audiences or website visitors — reaching people with browsing patterns similar to those who already visit your site.', tags: ['Video','similar-audiences','targeting','lookalike'] },
    { q: 'How should you approach your audience strategy for a video action campaign to convert intent into action?', options: ['Use only affinity audiences for broad reach','Avoid audience targeting to maximise reach','Use demographic targeting only','Start with lower-funnel audiences like remarketing and Customer Match, then expand to in-market and similar'], correct: 3, explanation: 'Video action campaign strategy: start lower-funnel (remarketing, Customer Match — highest purchase intent) then expand to in-market → similar segments → optimised targeting as you scale and need more volume.', tags: ['Video','action','audiência','remarketing','Customer-Match','funnel'] },
    { q: 'Why is it a good idea to opt into optimised targeting when creating a video action campaign?', options: ['It reduces your cost-per-view','It guarantees ad placement on YouTube homepage','It limits delivery to only your existing audience lists','It finds additional high-converting users beyond your manual audience selections using Google AI'], correct: 3, explanation: 'Optimised targeting for action campaigns uses Google AI to find users similar to your converters but outside your manually-defined audiences — expanding reach to high-intent users you would otherwise miss.', tags: ['Video','optimised-targeting','action','AI','conversions'] },
    { q: 'Why is it a good idea to opt in to Google video partners when creating an awareness video campaign?', options: ['It guarantees placement on the YouTube homepage','It reduces CPM by 50%','It limits delivery to premium publishers only','It extends reach to high-quality third-party publisher sites and apps beyond YouTube'], correct: 3, explanation: 'Google video partners extends your video ads beyond YouTube to a network of premium publishers (news sites, apps, entertainment platforms) — increasing total reach at efficient CPMs while maintaining brand-safe environments.', tags: ['Video','video-partners','reach','awareness','publisher'] },
    { q: 'You\'re creating a video campaign with brand awareness and reach as the goal. Why is tCPM the optimal bidding strategy?', options: ['tCPM optimises for lowest cost-per-click','tCPM guarantees top-of-page placement','tCPM is the only strategy for YouTube','tCPM optimises for reach by maximising the number of people who see your ad within your budget'], correct: 3, explanation: 'Target CPM (tCPM) bidding optimises for impressions at your target cost — maximising the number of unique people reached within budget. This aligns perfectly with awareness goals where reach is the primary objective.', tags: ['Video','tCPM','awareness','bidding','reach'] },
    { q: 'The goal of your video campaign is to grow consideration. What should your bidding solution optimise towards?', options: ['tCPM (target cost-per-thousand impressions)','tCPA (target cost-per-acquisition)','tROAS (target return on ad spend)','CPV (cost-per-view)'], correct: 3, explanation: 'CPV (cost-per-view) bidding optimises for video views — you pay when someone watches your ad for 30+ seconds (or full video if shorter) or interacts. This drives genuine consideration engagement at efficient view costs.', tags: ['Video','CPV','consideration','bidding'] },
    { q: 'It\'s your first time running a video action campaign. What bidding approach should you implement for optimal results?', options: ['Start with tROAS immediately','Use manual CPV bidding','Use Maximize clicks bidding','Start with Maximize conversions, then switch to tCPA after gathering 50+ conversions'], correct: 3, explanation: 'First-time video action campaigns should start with Maximize conversions (no target) to gather conversion data. After accumulating ~50+ conversions in 30 days, switch to tCPA for more controlled, efficient optimization.', tags: ['Video','action','bidding','Maximize-conversions','tCPA','learning'] },
    { q: 'During media planning, what can Reach Planner help with?', options: ['Setting optimal tCPA targets','Building remarketing lists','Creating video ad creative','Forecasting reach, frequency, and CPM for video campaigns across YouTube and video partners'], correct: 3, explanation: 'Reach Planner is a forecasting tool that predicts reach, frequency, and CPM for video campaigns — letting you plan and compare different media mixes (YouTube vs TV vs partners) before launching.', tags: ['Video','Reach-Planner','planning','forecast','reach','frequency'] },
    { q: 'What are the three primary benefits of Reach Planner?', options: ['Creative testing, bid optimization, and audience segmentation','Conversion tracking, remarketing, and attribution','Scheduling, brand safety, and viewability reporting','Audience-based planning, unique reach forecasting, and media mix comparisons across screens'], correct: 3, explanation: 'Reach Planner\'s three key benefits: audience-based reach planning (targeting specific audiences), unique reach forecasting (deduplicated across YouTube + partners), and cross-screen media mix comparison (YouTube vs TV vs partners).', tags: ['Video','Reach-Planner','audience','unique-reach','media-mix'] },
    { q: 'What do Insights Finder and Find My Audience help you do?', options: ['Set automated bidding rules','Create video ad creative','Manage bid adjustments by device','Discover audience insights and identify relevant audiences for your campaigns'], correct: 3, explanation: 'Insights Finder and Find My Audience are Google tools that help you understand your target audience\'s interests, behaviours, and demographics — identifying the best audience segments to target in your campaigns.', tags: ['Video','Insights-Finder','Find-My-Audience','audiência','discovery'] },
    { q: 'You\'re running a video action campaign to drive online sales. What extension should you add?', options: ['Call extension','Location extension','Sitelink extension','Product feed extension'], correct: 3, explanation: 'Product feed extensions connect your Google Merchant Center catalog to video action campaigns — showing relevant products from your feed directly in the ad, making it easier for viewers to click and buy specific products.', tags: ['Video','action','product-feed','Merchant-Center','e-commerce'] },
    { q: 'You want to understand how many people watched key moments or skipped your video ad. Which tool should you use?', options: ['Reach Planner','Google Analytics 4','Google Ads Editor','Video Creative Analytics'], correct: 3, explanation: 'Video Creative Analytics shows moment-by-moment audience retention curves for your video ads — revealing exactly when viewers drop off, where they skip, and which moments hold attention longest.', tags: ['Video','Video-Creative-Analytics','retenção','skip','análise'] },
    { q: 'What\'s a benefit of using Google\'s video solutions for awareness, consideration, or action goals?', options: ['They eliminate the need for creative testing','They guarantee 100% viewability','They provide guaranteed placements on competitor channels','They reach people across YouTube, Google video partners, and connected TV in a single campaign'], correct: 3, explanation: 'Google video solutions offer unified reach across YouTube (the largest video platform), Google video partners (premium third-party publishers), and connected TV (YouTube on TV screens) — all in one campaign setup.', tags: ['Video','YouTube','video-partners','CTV','connected-TV'] },
  ]
};

// ── GOOGLE ADS MEASUREMENT CERTIFICATION ──
window.__quizData['google_measurement'] = {
  id: 'google_measurement',
  cert: 'Google Ads Measurement Certification',
  icon: '📏',
  source: 'Google Skillshop',
  url: 'https://skillshop.docebosaas.com/learn/courses/18539/google-ads-measurement-certification',
  questions: [
    { q: 'What is conversion modeling?', options: ['A bidding strategy that optimises for conversions','A tool that predicts future campaign performance','A method to manually assign conversion values','A privacy-safe technique using ML to estimate conversions that can\'t be directly observed due to privacy restrictions or consent gaps'], correct: 3, explanation: 'Conversion modeling uses machine learning to estimate conversions from users who didn\'t consent to tracking — filling the measurement gap caused by privacy restrictions (ITP, consent mode, ad blockers) while respecting user privacy.', tags: ['Measurement','conversion-modeling','ML','privacidade','Consent-Mode'] },
    { q: 'Which scenario describes why an advertiser should implement Consent Mode?', options: ['To increase ad delivery to opted-in users only','To replace conversion tracking entirely','To block cookies from all users in EU','An advertiser running campaigns in the EU where users can decline tracking cookies, causing measurement gaps that Consent Mode fills with modeled conversions'], correct: 3, explanation: 'Consent Mode is implemented when users can decline tracking consent (common in EU under GDPR). When declined, the Google tag doesn\'t fire tracking cookies — Consent Mode uses behavioral modeling to fill measurement gaps.', tags: ['Measurement','Consent-Mode','GDPR','EU','privacidade'] },
    { q: 'What is conversion modeling\'s primary benefit for advertisers using Consent Mode?', options: ['It increases bid amounts automatically','It bypasses user consent requirements','It makes ads more visually appealing','It recovers estimated conversion data from users who declined consent, maintaining measurement accuracy'], correct: 3, explanation: 'Consent Mode\'s conversion modeling reconstructs estimated conversion rates from consented users to fill gaps from non-consented users — maintaining ~95%+ measurement accuracy even with significant consent opt-out rates.', tags: ['Measurement','Consent-Mode','conversion-modeling','acurácia'] },
    { q: 'A marketer wants to track product newsletter sign-ups. What type of conversion action would this be?', options: ['Sales','Phone calls','App conversions','Lead'], correct: 3, explanation: 'Newsletter sign-ups are Lead conversions — they indicate user interest and provide contact information for follow-up, but aren\'t direct sales. Google Ads conversion categories: Sales, Leads, Page views, Phone calls, App downloads.', tags: ['Measurement','conversions','lead','sign-up','category'] },
    { q: 'What\'s the definition of a tag, as it pertains to digital advertising?', options: ['A keyword used to categorize ad groups','A label applied to conversion events in GA4','A snippet of code placed on a website or app to collect and send data to a platform like Google Ads or Analytics','A visual label displayed on ad creatives'], correct: 2, explanation: 'A tag is a snippet of JavaScript code placed on your website/app that fires when a user takes an action — collecting data (clicks, conversions, page views) and sending it to measurement platforms like Google Ads or GA4.', tags: ['Measurement','tag','código','JavaScript','tracking'] },
    { q: 'What\'s a requirement for implementing sitewide tagging?', options: ['You must use Google Tag Manager exclusively','You must have a Google Analytics 360 subscription','Your website must be built with a specific CMS','The Google tag (gtag.js) or Google Tag Manager must be present on every page of your website'], correct: 3, explanation: 'Sitewide tagging requires the Google tag (gtag.js) or GTM container on ALL pages — not just conversion pages. This enables cross-page journey tracking, remarketing audience building, and accurate conversion attribution.', tags: ['Measurement','sitewide-tagging','Google-tag','GTM','implementação'] },
    { q: 'How would a digital marketing consultant describe the Google tag to a new advertiser?', options: ['A tool that creates ad copy automatically','A dashboard for viewing campaign metrics','A bidding strategy powered by machine learning','A single piece of code you add to your website once that handles all Google tracking including Ads, Analytics, and Floodlight'], correct: 3, explanation: 'The Google tag (gtag.js) is a unified, site-wide tag that powers multiple Google products (Ads, Analytics, Floodlight) from a single code snippet — replacing the need for separate tags for each product.', tags: ['Measurement','Google-tag','gtag','unified','implementação'] },
    { q: 'What are two capabilities of Google Tag Manager? (select two)', options: ['Automatically creating ad creative','Setting Smart Bidding targets','Replacing Google Analytics entirely','Deploying and managing website tags without code changes','Testing tags in a debugging environment before publishing'], correct: [3,4], explanation: 'GTM enables: (1) deploying/managing tags without direct code changes (via the GTM interface), and (2) debugging/testing tags in Preview mode before publishing to live users. It\'s a tag management layer, not a measurement tool itself.', tags: ['Measurement','GTM','tag-management','deploy','debug'] },
    { q: 'What\'s the first step in setting up conversion tracking in Google Ads?', options: ['Install the remarketing tag','Create a Smart Bidding strategy','Link Google Ads to Google Analytics','Define the conversion action (what counts as a conversion and how to measure it)'], correct: 3, explanation: 'Before any technical implementation, you first define the conversion action: what event counts (purchase, lead, call), how to count (every conversion vs one per click), value, and attribution window. Then you implement the tag.', tags: ['Measurement','conversion-tracking','setup','primeiro-passo'] },
    { q: 'How are phone calls tracked in Google\'s phone call conversion tracking?', options: ['Via the advertiser\'s CRM system','Through call recording transcripts','Using a unique Google forwarding number displayed to each user that tracks calls back to the specific ad click','Through the user\'s mobile carrier data'], correct: 2, explanation: 'Google dynamically inserts a unique forwarding phone number for each user session. When the user calls that number, it routes to the advertiser\'s real number while Google records the call duration and attributes it to the specific ad/keyword click.', tags: ['Measurement','phone-calls','forwarding-number','conversion-tracking'] },
    { q: 'What\'s one reason advertisers should adopt enhanced conversions for web?', options: ['It replaces the need for conversion tags entirely','It allows advertisers to show ads to opted-out users','It increases click-through rates automatically','It recovers lost conversion data by matching hashed first-party customer data to Google accounts'], correct: 3, explanation: 'Enhanced conversions for web captures first-party data (email, name, etc.) from conversion pages, hashes it, and sends it to Google. This allows matching to signed-in Google users even when cookies are blocked, recovering lost conversions.', tags: ['Measurement','enhanced-conversions','web','hashing','first-party'] },
    { q: 'When a consumer completes a conversion, you collect their email address. This can be sent to Google in hashed form through which GA4 feature?', options: ['Custom dimensions','Audience segments','Event parameters','Enhanced conversions / User data collection'], correct: 3, explanation: 'GA4\'s enhanced conversions (user-provided data) feature collects first-party data at conversion points, automatically hashes it (SHA-256), and sends it to Google for cross-device attribution and conversion recovery.', tags: ['Measurement','GA4','enhanced-conversions','hashing','email'] },
    { q: 'A marketer added a conversion tag to a landing page and found duplicate conversions. How can they remove them?', options: ['Delete duplicate conversion actions','Pause the campaign and restart','Reduce the conversion window','Use transaction IDs in the conversion tag to deduplicate conversions'], correct: 3, explanation: 'Transaction IDs (order IDs) in conversion tags allow Google to deduplicate — if the same transaction ID fires twice (page refresh, back button), Google only counts it once. Essential for e-commerce purchase tracking accuracy.', tags: ['Measurement','deduplication','transaction-ID','conversion-tag'] },
    { q: 'How does data-driven attribution work?', options: ['It assigns 100% credit to the last click','It equally distributes credit across all touchpoints','It randomly assigns credit based on position','It uses machine learning to analyze your account\'s actual conversion paths and assigns fractional credit to each touchpoint based on its real contribution'], correct: 3, explanation: 'DDA uses ML to analyze the actual paths that led to conversions vs paths that didn\'t — identifying which touchpoints (keywords, ads, placements) truly contributed and assigning fractional credit based on real impact, not rules.', tags: ['Measurement','data-driven-attribution','DDA','ML','atribuição'] },
    { q: 'A marketing analyst wants to see how changes to their attribution model might impact conversion reporting. What report provides this?', options: ['Auction insights report','Keyword planner report','Reach and frequency report','Model comparison report in the Attribution section of Google Ads'], correct: 3, explanation: 'The Model Comparison report (Attribution > Model comparison in Google Ads) shows how different attribution models (last click, first click, linear, time decay, data-driven) would value each keyword/campaign — without changing your active model.', tags: ['Measurement','model-comparison','attribution','report','Google-Ads'] },
    { q: 'Which Attribution settings govern conversions in the Conversion Performance Report in GA4\'s Advertising workspace?', options: ['Last click attribution only','Data-driven attribution only','Time decay attribution only','The attribution model and lookback window configured in the Attribution settings of the GA4 property'], correct: 3, explanation: 'The GA4 Attribution settings (in Admin > Attribution settings) define the attribution model and conversion lookback window that govern all attribution-based reports in the Advertising workspace, including Conversion paths and Model comparison.', tags: ['Measurement','GA4','attribution','Advertising-workspace','lookback'] },
    { q: 'When Google Ads is linked to GA4, how can conversion events from GA4 be used in Google Ads?', options: ['Only for reporting, not optimization','To adjust geographic targeting','To generate ad creative automatically','To optimize Smart Bidding — GA4 conversions imported into Google Ads serve as the optimization signal for tCPA, tROAS, and Maximize conversions'], correct: 3, explanation: 'GA4 key events imported into Google Ads as conversion actions become available as Smart Bidding optimization targets — Google\'s AI uses them as the signal to find users most likely to convert.', tags: ['Measurement','GA4','Google-Ads','Smart-Bidding','conversions'] },
    { q: 'A marketing strategist is interested in target ROAS bidding. How might their agency describe this strategy?', options: ['It maximises clicks within your budget','It sets a fixed CPC for each keyword','It automatically pauses low-performing keywords','An AI-powered bidding strategy that adjusts bids to achieve your desired return on ad spend, maximising conversion value while hitting your ROAS target'], correct: 3, explanation: 'Target ROAS tells Google\'s AI your desired return (e.g., 400% ROAS = $4 revenue per $1 spent) and it automatically adjusts bids across auctions to maximize total conversion value while maintaining that target.', tags: ['Measurement','tROAS','Smart-Bidding','ROAS','AI'] },
    { q: 'What do marketing mix models show advertisers?', options: ['Which ad creatives perform best A/B tests','How individual keywords contribute to conversions','Which keywords have highest Quality Score','The contribution of each marketing channel (TV, digital, OOH, etc.) to overall sales and ROI across the entire media mix'], correct: 3, explanation: 'MMMs use statistical regression to analyze historical data and quantify each channel\'s contribution to business outcomes (sales, revenue) — enabling budget allocation decisions across all channels, online and offline.', tags: ['Measurement','MMM','marketing-mix-model','atribuição','canais'] },
    { q: 'In which scenario should an advertiser use incrementality measurement?', options: ['When setting up new conversion tags','When comparing creative performance','When choosing keywords for a Search campaign','When they want to measure the true causal impact of advertising by comparing exposed vs control groups to quantify what wouldn\'t have happened without the ads'], correct: 3, explanation: 'Incrementality (lift studies, geo experiments) answers: "Would these conversions have happened anyway?" by comparing a test group (saw ads) vs holdout group (didn\'t). It measures TRUE incremental impact, not correlated conversions.', tags: ['Measurement','incrementality','lift-study','causalidade','holdout'] },
    { q: 'How are incrementality experiments different from A/B experiments?', options: ['Incrementality experiments test ad creative; A/B tests different audience segments','Incrementality measures creative performance; A/B measures bidding strategies','There is no difference between them','Incrementality measures the causal impact of whether advertising drives additional conversions; A/B experiments compare two variants to determine which performs better'], correct: 3, explanation: 'A/B tests compare two variants (which ad, bid, landing page performs better). Incrementality tests measure the TRUE lift from advertising — would users have converted without seeing the ad at all? It answers a different, more fundamental question.', tags: ['Measurement','incrementality','A/B','causalidade','lift'] },
    { q: 'You want to see how users from paid search progress through a checkout funnel on your site. Which GA4 exploration technique should you use?', options: ['Free form exploration','Cohort exploration','Segment overlap','Funnel exploration'], correct: 3, explanation: 'Funnel exploration in GA4 Explore lets you define steps in a conversion process and see how users progress (or drop off) at each step — identifying where in the checkout funnel paid search users abandon.', tags: ['Measurement','GA4','Funnel-exploration','checkout','paid-search'] },
    { q: 'You\'ve been discussing first-party data strategy with your client. How would you explain its benefit?', options: ['First-party data is cheaper than third-party data subscriptions','First-party data improves ad delivery speed','First-party data requires no privacy compliance','First-party data is directly collected from your own customers, making it more accurate, privacy-compliant, and sustainable as third-party cookies are phased out'], correct: 3, explanation: 'First-party data (collected directly from your customers with consent) is more accurate than third-party data, is sustainable post-cookie deprecation, complies with privacy regulations, and enables personalized measurement and targeting that third-party data can\'t match.', tags: ['Measurement','first-party-data','cookies','privacidade','LGPD'] },
    { q: 'An advertiser is concerned about implementing enhanced conversions because it includes conversion modeling. Which three features are benefits of conversion modeling?', options: ['It bypasses consent requirements','It increases raw traffic volume','It replaces your existing tracking tag','It fills gaps from users who decline consent','It maintains measurement accuracy when cookies are restricted','It enables Smart Bidding to optimize despite signal loss'], correct: [3,4,5], explanation: 'Conversion modeling benefits: (1) fills consent gaps — estimates conversions from opted-out users; (2) maintains accuracy when cookies are blocked (ITP, ad blockers); (3) enables Smart Bidding to continue optimizing even with partial signal, preserving campaign performance.', tags: ['Measurement','conversion-modeling','Smart-Bidding','consent','signal-loss'] },
    { q: 'You\'re running a Video Reach Campaign and want to implement a Brand Lift study. Which two considerations should you keep in mind?', options: ['Brand Lift requires a minimum of 1,000 conversions','Brand Lift is only available for Search campaigns','Brand Lift is free and unlimited for all advertisers','Brand Lift has minimum spend thresholds that must be met before it activates','Brand Lift measures awareness and consideration metrics, not sales'], correct: [3,4], explanation: 'Brand Lift considerations: (1) minimum spend/impression thresholds are required before the study activates (varies by country/format); (2) it measures upper-funnel metrics (ad recall, awareness, consideration) not direct sales/conversions.', tags: ['Measurement','Brand-Lift','VRC','minimum-spend','awareness'] },
    { q: 'Your client\'s CEO wants the ROI of their entire annual marketing budget across online and offline channels. Which measurement solution should they use?', options: ['Google Ads conversion reports','GA4 attribution reports','Google Ads Brand Lift studies','Marketing Mix Model (MMM)'], correct: 3, explanation: 'MMM is the right solution for total portfolio ROI — it analyzes all channels (TV, digital, OOH, search, social) simultaneously using historical data to quantify each channel\'s contribution and overall marketing ROI.', tags: ['Measurement','MMM','ROI','portfolio','CEO','offline'] },
    { q: 'Only half your users consented for analytics. Which feature fills measurement gaps while respecting privacy?', options: ['Enhanced conversions','Customer Match','Tag Manager','GA4 behavioral modeling (Consent Mode + Modeling)'], correct: 3, explanation: 'GA4\'s behavioral modeling (enabled via Consent Mode) fills in the gaps from non-consented users by modeling their behavior based on similar consented users — maintaining reporting accuracy while fully respecting consent choices.', tags: ['Measurement','GA4','behavioral-modeling','Consent-Mode','privacidade'] },
    { q: 'You\'re running a Video reach campaign and want to forecast cross-media reach. What tool should be used as the first step?', options: ['Google Analytics 4 Explore','Brand Lift measurement','Google Ads Keyword Planner','Reach Planner'], correct: 3, explanation: 'Reach Planner is the first step for cross-media reach planning — it forecasts unique reach, frequency, and CPM across YouTube and video partners, and allows comparison with TV reach plans to optimize total video investment.', tags: ['Measurement','Reach-Planner','cross-media','forecast','YouTube','TV'] },
    { q: 'What is the value of each lead if 50 leads generate 25 consumers worth $100 each on average?', options: ['$100','$200','$25','$50'], correct: 3, explanation: 'Lead value = (conversions × value) ÷ leads = (25 × $100) ÷ 50 = $2,500 ÷ 50 = $50 per lead. This lead value can then be used as the conversion value in Google Ads to enable value-based Smart Bidding.', tags: ['Measurement','lead-value','conversão','cálculo','Smart-Bidding'] },
    { q: 'How can an advertiser set up enhanced conversions for leads?', options: ['By enabling auto-tagging in Google Ads','By importing GA4 goals into Google Ads','By installing the Google Display Network tag','By capturing hashed user-provided data (email, name, phone) from lead form submissions and sending it to Google Ads via the tag or API'], correct: 3, explanation: 'Enhanced conversions for leads captures first-party data from lead form submissions (email, name, phone), hashes it server-side, and sends it to Google Ads — enabling better attribution and signal for Smart Bidding even without cookie-based tracking.', tags: ['Measurement','enhanced-conversions','leads','hashing','first-party'] },
    { q: 'Your client wants to compare YouTube campaign performance against other video channels. Which two metrics should they use?', options: ['Click-through rate and Cost-per-click','Impression share and Quality Score','CPM and CPC','Reach and Cost-Per-Point (CPP)'], correct: 3, explanation: 'For cross-channel video comparison, use Reach (unique viewers — comparable across platforms) and Cost-Per-Point (CPP — cost to reach 1% of the target audience), which are standard media planning metrics across TV and digital video.', tags: ['Measurement','YouTube','cross-channel','reach','CPP','comparação'] },
  ]
};
